CREATE OR ALTER PROCEDURE ventas.usp_crear_pedido
  @cliente_id INT,
  @pedido_id  INT OUTPUT
AS
BEGIN
  SET NOCOUNT ON;
  IF NOT EXISTS (SELECT 1 FROM ventas.clientes WHERE id = @cliente_id)
    RETURN 1;                             -- código: cliente inexistente

  INSERT INTO ventas.pedidos (cliente_id, fecha, estado)
  VALUES (@cliente_id, CAST(GETDATE() AS DATE), 'pendiente');

  SET @pedido_id = SCOPE_IDENTITY();
  RETURN 0;
END;
