CREATE OR ALTER PROCEDURE fin.usp_transferir
  @origen INT, @destino INT, @monto DECIMAL(19,4)
AS
BEGIN
  SET NOCOUNT ON;
  IF @monto <= 0
    THROW 50001, 'El monto debe ser positivo.', 1;
  IF @origen = @destino
    THROW 50002, 'La cuenta de origen y destino son la misma.', 1;
  IF (SELECT saldo FROM fin.cuentas WHERE id = @origen) < @monto
    THROW 50003, 'Saldo insuficiente.', 1;
  -- … el movimiento va en el capítulo 11, dentro de una transacción
END;

CREATE OR ALTER PROCEDURE ventas.usp_buscar_clientes
  @pais   NVARCHAR(50) = NULL,
  @nombre NVARCHAR(100) = NULL,
  @orden  SYSNAME = N'nombre'
AS
BEGIN
  SET NOCOUNT ON;
  IF @orden NOT IN (N'nombre', N'pais', N'fecha_registro')
    THROW 50010, 'Columna de orden no permitida.', 1;

  DECLARE @sql NVARCHAR(MAX) = N'SELECT id, nombre, pais FROM ventas.clientes WHERE 1 = 1';
  IF @pais   IS NOT NULL SET @sql += N' AND pais = @pais';
  IF @nombre IS NOT NULL SET @sql += N' AND nombre LIKE @nombre + N''%''';
  SET @sql += N' ORDER BY ' + QUOTENAME(@orden) + N';';

  EXEC sys.sp_executesql @sql,
       N'@pais NVARCHAR(50), @nombre NVARCHAR(100)',
       @pais = @pais, @nombre = @nombre;
END;

