CREATE OR ALTER PROCEDURE fin.usp_transferir
  @origen INT, @destino INT, @monto DECIMAL(19,4)
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON;
  IF @monto <= 0 THROW 50001, 'El monto debe ser positivo.', 1;

  BEGIN TRY
    BEGIN TRAN;
      UPDATE fin.cuentas SET saldo = saldo - @monto
      WHERE id = @origen AND saldo >= @monto;
      IF @@ROWCOUNT = 0 THROW 50003, 'Saldo insuficiente o cuenta inexistente.', 1;

      UPDATE fin.cuentas SET saldo = saldo + @monto WHERE id = @destino;
      IF @@ROWCOUNT = 0 THROW 50004, 'La cuenta de destino no existe.', 1;

      INSERT INTO fin.movimientos (cuenta, fecha, monto) VALUES
        (@origen, SYSDATETIME(), -@monto), (@destino, SYSDATETIME(), @monto);
    COMMIT;
  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK;
    THROW;
  END CATCH;
END;

